def f(I):
    H,W=len(I),len(I[0])
    cnt={}
    for r in I:
        for x in r: cnt[x]=cnt.get(x,0)+1
    tcol=max(cnt,key=cnt.get)
    nb=[(r,c) for r in range(H) for c in range(W) if I[r][c]==tcol]
    r0=min(r for r,c in nb); r1=max(r for r,c in nb)
    c0=min(c for r,c in nb); c1=max(c for r,c in nb)
    tmpl=[[I[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
    keyrow=[r for r in range(H) if any(x!=tcol and x!=0 for x in I[r])]
    # key row: row containing key colors
    kr=max(keyrow,key=lambda r:max(set(x for x in I[r] if x!=tcol and x!=0)))
    kc=sorted({x for x in I[kr] if x!=tcol and x!=0})
    n=len(kc)
    out=[[0]*W for _ in range(H)]
    hgt=len(tmpl)
    # contiguous stack centered on original: (n//2) copies above, (n-n//2) below, original in middle
    above=n//2; below=n-n//2
    for i,col in enumerate(kc[:above]):
        base=r0-(i+1)*hgt-1  # adjacent above, stacking from top
        for dr in range(hgt):
            for dc in range(len(tmpl[0])):
                if tmpl[dr][dc]:
                    rr=base+dr; cc=c0+dc
                    if 0<=rr<H: out[rr][cc]=col
    for i,col in enumerate(kc[above:]):
        base=r1+1+i*hgt
        for dr in range(hgt):
            for dc in range(len(tmpl[0])):
                if tmpl[dr][dc]:
                    rr=base+dr; cc=c0+dc
                    if 0<=rr<H: out[rr][cc]=col
    # keep original
    for r in range(r0,r1+1):
        for c in range(c0,c1+1):
            out[r][c]=tcol if I[r][c]==tcol else 0
    return out

